/**
 * THE WRITE STORM — does the renderer survive thirty small writes in a row?
 *
 * SEEN (the children's book in CLI mode): a 4B wrote thirty ~400-byte markdown
 * "illustration descriptions" in two minutes, the Activity tab morphing to each
 * one, and the window stopped answering — page.evaluate and page.screenshot
 * both hung for over thirty seconds. That is the renderer-freeze class the user
 * said cannot happen. This replays the same shape through mock-pi (fixture
 * generated by the script beside it) and measures how long the renderer takes
 * to answer a trivial evaluate after every write; any answer over a second is
 * the finding.
 *
 *   FIXTURE  path to the write-storm fixture (default /tmp/write-storm/fixture.json)
 *   OUT      screenshots (default /tmp/write-storm)
 */
import { existsSync, mkdirSync, mkdtempSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { _electron as electron } from 'playwright-core';

const require = createRequire(import.meta.url);
const electronBinary = require('electron');
const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const repoRoot = path.resolve(appRoot, '../..');
const mockPi = path.join(repoRoot, 'packages/engine/tools/mock-pi/mock-pi.mjs');
const FIXTURE = process.env.FIXTURE ?? '/tmp/write-storm/fixture.json';
const OUT = process.env.OUT ?? '/tmp/write-storm';
mkdirSync(OUT, { recursive: true });
if (!existsSync(FIXTURE)) throw new Error(`no fixture at ${FIXTURE}`);

const t0 = Date.now();
const say = (m) => console.log(`${((Date.now() - t0) / 1000).toFixed(1)}s  ${m}`);

const app = await electron.launch({
  executablePath: electronBinary,
  args: [appRoot, `--user-data-dir=${mkdtempSync(path.join(tmpdir(), 'write-storm-udd-'))}`],
  env: {
    ...process.env,
    PI_E2E: '1',
    PI_E2E_BACKGROUND: '1',
    PI_E2E_NO_SERVER: '1',
    PI_BIN: mockPi,
    MOCK_PI_FIXTURE: FIXTURE,
  },
});
const errors = [];
app.process().stderr?.on('data', (d) => {
  for (const line of String(d).split('\n'))
    if (/error|Error|unresponsive|crash/i.test(line)) errors.push(line.slice(0, 240));
});

try {
  const win = await app.firstWindow();
  await win.waitForFunction(() => typeof window.__pi_store === 'function', { timeout: 60000 });
  await win.waitForTimeout(1500);
  win.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(`renderer: ${msg.text().slice(0, 4000)}`);
  });
  const editor = win.locator('[contenteditable="true"]').first();
  await editor.click();
  await win.keyboard.type('write the descriptions', { delay: 2 });
  await win.keyboard.press('Enter');
  say('sent');

  // Responsiveness: a trivial evaluate, timed, with its own deadline.
  const ping = async () => {
    const at = Date.now();
    try {
      await Promise.race([
        win.evaluate(() => 1),
        new Promise((_, reject) => setTimeout(() => reject(new Error('ping timeout')), 15000)),
      ]);
      return Date.now() - at;
    } catch {
      return -1;
    }
  };
  let worst = 0;
  let hung = 0;
  let writes = 0;
  const deadline = Date.now() + 240_000;
  while (Date.now() < deadline) {
    const ms = await ping();
    if (ms < 0) {
      hung += 1;
      say('RENDERER DID NOT ANSWER IN 15 s');
      break;
    }
    worst = Math.max(worst, ms);
    const st = await win.evaluate(() => {
      const s = window.__pi_store().getState();
      let n = 0;
      for (const m of s.messages) if (m.kind === 'toolResult') n += 1;
      return {
        results: n,
        streaming: s.agent.isStreaming,
        tab: document.querySelector('[data-testid="canvas-tab"]')?.textContent ?? null,
      };
    });
    if (st.results !== writes) {
      writes = st.results;
      if (writes % 5 === 0) say(`${writes} writes landed · worst ping ${worst} ms`);
    }
    if (!st.streaming && writes >= Number(process.env.WRITES ?? 30)) break;
    await win.waitForTimeout(150);
  }
  await win.screenshot({ path: path.join(OUT, 'end.png') });
  say(`DONE — ${writes} writes, worst ping ${worst} ms, hung: ${hung}`);
  if (errors.length > 0) {
    say(`errors (${errors.length}):`);
    for (const e of errors.slice(0, 12)) console.log(`  ${e}`);
  }
} finally {
  await app.close().catch(() => {});
}
